THLY" }, label = { Text("Bulanan") }) }; NumberField(salary, { salary = it }, "Gaji pokok", Modifier.fillMaxWidth()); NumberField(meal, { meal = it }, "Uang makan / hari", Modifier.fillMaxWidth()); NumberField(otMeal, { otMeal = it }, "Makan lembur / hari", Modifier.fillMaxWidth()); NumberField(otRate, { otRate = it }, "Tarif lembur / jam", Modifier.fillMaxWidth()) } }, confirmButton = { Button(onClick = { if (name.isNotBlank()) save(Employee(name = name, position = position, salaryType = type, baseSalary = salary.toLongOrNull() ?: 0, mealDaily = meal.toLongOrNull() ?: 0, mealOvertime = otMeal.toLongOrNull() ?: 0, overtimeRate = otRate.toLongOrNull() ?: 0, standardWorkDays = if (type == "MONTHLY") 26 else 6)) }, colors = ButtonDefaults.buttonColors(containerColor = Charcoal)) { Text("Simpan") } }, dismissButton = { TextButton(onClick = close) { Text("Batal") } })
