    AlertDialog(onDismissRequest = close, title = { Text("Data Perusahaan") }, text = { Column(verticalArrangement = Arrangement.spacedBy(8.dp)) {
        OutlinedTextField(name, { name = it }, label = { Text("Nama perusahaan") }); OutlinedTextField(address, { address = it }, label = { Text("Alamat") }); OutlinedTextField(contact, { contact = it }, label = { Text("Kontak") })
        Text("Asset dokumen", fontWeight = FontWeight.Bold);
        Row(horizontalArrangement = Arrangement.spacedBy(6.dp)) { Button(onClick = { target = "logo"; picker.launch("image/*") }, colors = ButtonDefaults.buttonColors(containerColor = Yellow), contentColor = Charcoal) { Text(if (logo == null) "Logo" else "✓ Logo") }; Button(onClick = { target = "signature"; picker.launch("image/*") }, colors = ButtonDefaults.buttonColors(containerColor = Yellow), contentColor = Charcoal) { Text(if (signature == null) "Tanda tangan" else "✓ TTD") }; Button(onClick = { target = "stamp"; picker.launch("image/*") }, colors = ButtonDefaults.buttonColors(containerColor = Yellow), contentColor = Charcoal) { Text(if (stamp == null) "Cap" else "✓ Cap") } }
    } }, confirmButton = { Button(onClick = { save(initial.copy(name = name, address = address, contact = contact, logoUri = logo, signatureUri = signature, stampUri = stamp)) }, colors = ButtonDefaults.buttonColors(containerColor = Charcoal)) { Text("Simpan") } }, dismissButton = { TextButton(onClick = close) { Text("Batal") } })
}

