private fun shareSlip(context: Context, row: PayrollRow) {
    val pdf = PdfDocument(); val page = pdf.startPage(PdfDocument.PageInfo.Builder(595, 842, 1).create()); val canvas = page.canvas; val p = Paint().apply { color = android.graphics.Color.BLACK; textSize = 16f }
    var y = 55f; canvas.drawText("SLIP GAJI", 45f, y, p); y += 28; p.textSize = 13f; canvas.drawText(row.employee.name, 45f, y, p); y += 20; canvas.drawText(row.employee.position, 45f, y, p); y += 30
    listOf("Hari kerja: ${row.days}", "Gaji pokok: ${rupiah(row.base)}", "Uang makan: ${rupiah(row.meal)}", "Lembur: ${row.overtime} jam / ${rupiah(row.overtimePay)}", "Makan lembur: ${rupiah(row.overtimeMeal)}"